(function(root){'use strict';
function gcd(a,b){return b?gcd(b,a%b):Math.abs(a)||1;}
function fraction(n,d){const g=gcd(n,d);return {n:n/g,d:d/g,value:n/d};}
function parseAnswer(raw){const s=String(raw).trim().replace(/\s/g,'').replace(',','.');let v;if(/^\d+\/\d+$/.test(s)){const [n,d]=s.split('/').map(Number);if(!d)return null;v=n/d;}else if(/^(?:\d+(?:\.\d*)?|\.\d+)%$/.test(s))v=Number(s.slice(0,-1))/100;else if(/^(?:\d+(?:\.\d*)?|\.\d+)$/.test(s))v=Number(s);else return null;return Number.isFinite(v)&&v>=0&&v<=1?v:null;}
function isCorrect(raw,q){const v=parseAnswer(raw);return v!==null&&Math.abs(v-q.value)<=0.000051;}
function makeQuestion(cards,kind){const N=cards.length;if(!N)return null;const G=cards.filter(c=>c.role==='guard').length,A=cards.filter(c=>c.role==='attack').length,F=cards.filter(c=>c.element==='fire').length,I=cards.filter(c=>c.element==='fire'&&c.role==='attack').length;
 let n,d,text,formula,why,label,steps;
 if(kind==='single'){n=G;d=N;text='What is the chance to draw a Defense card?';formula=G+'/'+N;why='Each card has the same chance. Divide the number of Defense cards by all cards in the Draw Pile.';label='Single event';steps=[G+' Defense cards',N+' cards in the source','P(Defense) = '+formula];}
 else if(kind==='exclusive'){n=A+G;d=N;text='What is the chance to draw an Attack OR a Defense card?';formula=A+'/'+N+' + '+G+'/'+N;why='A card has only one type. It cannot be both Attack and Defense. These events are mutually exclusive.';label='Mutually exclusive';steps=['Attack = '+A+', Defense = '+G,'Overlap = 0','P(A or B) = '+formula];}
 else if(kind==='overlap'){n=A+F-I;d=N;text='What is the chance to draw a Fire OR an Attack card?';formula='('+F+' + '+A+' − '+I+') / '+N;why='A Fire Attack card is in both groups. Subtract the overlap so each card is counted once.';label='Not mutually exclusive';steps=['Fire = '+F+', Attack = '+A,'Fire and Attack = '+I,'P(A or B) = '+formula];}
 else {if(N<2)return null;
  if(kind==='pairWithout'){n=G*(G-1);d=N*(N-1);text='What is the chance to draw two Defense cards WITHOUT replacement?';formula=G+'/'+N+' × '+Math.max(0,G-1)+'/'+(N-1);why='Keep the first card out. After a Defense card is drawn, there is one fewer Defense card and one fewer card in total. With no Defense cards, the chance is zero.';label='Without replacement';steps=['First draw: '+G+'/'+N,'After the first Defense card: '+Math.max(0,G-1)+'/'+(N-1),'P(two Defense cards) = '+formula];}
  else if(kind==='pairWith'){n=G*G;d=N*N;text='What is the chance to draw two Defense cards WITH replacement and a shuffle?';formula=G+'/'+N+' × '+G+'/'+N;why='Put the first card back and shuffle. The card counts stay the same, so the two draws are independent.';label='With replacement';steps=['First draw: '+G+'/'+N,'Put it back and shuffle','P(two Defense cards) = '+formula];}
  else {kind='atLeast';const B=N-G;n=N*(N-1)-B*(B-1);d=N*(N-1);text='What is the chance to draw AT LEAST one Defense card in two draws without replacement?';formula='1 − ('+B+'/'+N+' × '+Math.max(0,B-1)+'/'+(N-1)+')';why='Use the complement: 1 minus the chance that both cards are not Defense.';label='Complementary event';steps=['Not Defense = '+B,'P(no Defense cards) = '+B+'/'+N+' × '+Math.max(0,B-1)+'/'+(N-1),'P(at least one) = '+formula];}}
 const f=fraction(Math.max(0,n),d);return {...f,kind,text,formula,why,label,steps,total:N,counts:{guard:G,attack:A,fire:F,intersection:I},source:cards.map(c=>({...c})),attempts:0,hinted:false,solved:false};}
const M={gcd,fraction,parseAnswer,isCorrect,makeQuestion};if(typeof module!=='undefined')module.exports=M;else root.DCMath=M;
})(typeof window!=='undefined'?window:globalThis);
